    '中国では、春節(旧正月)は1年で最も重要な祝日です。多くの工場は1月下旬から休みに入り、休暇は通常2週間ほどですが、さらに長く休む工場もあります。\n春節前後は物流も大きな影響を受けます。節前は注文が集中して船腹が逼迫し、節後は帰省した労働者が戻らず、生産の回復に時間がかかります。\nそのため、中国の工場と取引する際は、2〜3か月前に春節前後の生産・出荷スケジュールを確認し、必要に応じて事前に在庫を確保するのが望ましいです。',
